const kot = {
  imie: "Filemon",
  miauknij() {
    console.log(`${this.imie} mowi: Miau!`);
  },
};

kot.miauknij(); // "Filemon mowi: Miau!"

const samochod = {
  marka: "Toyota",
  predkosc: 0,
  przyspiesz(o) {
    this.predkosc += o;
  },
};

samochod.przyspiesz(20);
samochod.przyspiesz(20);
console.log(samochod.predkosc); // 40

function pokazTo() {
  console.log(this);
}

pokazTo();
// this okazalo sie undefined (modul ES dziala w trybie strict) - funkcja
// NIE zostala wywolana przez zaden obiekt (brak kropki przed nawiasem),
// wiec brak "kontekstu", ktory this moglby wskazac.

const sklep = {
  nazwa: "Kwiaciarnia u Ani",
  podajNazwe() {
    return this.nazwa;
  },
};

const wynik = sklep.podajNazwe();
console.log(wynik); // "Kwiaciarnia u Ani"

function podajNazwe() {
  return this.nazwa;
}

const sklepA = { nazwa: "A", podajNazwe };
const sklepB = { nazwa: "B", podajNazwe };

console.log(sklepA.podajNazwe()); // "A"
console.log(sklepB.podajNazwe()); // "B" - ta sama funkcja, inny this

const licznik = {
  wartosc: 0,
  zwieksz() {
    this.wartosc++;
    return this.wartosc;
  },
};

console.log(licznik.zwieksz()); // 1
console.log(licznik.zwieksz()); // 2
console.log(licznik.zwieksz()); // 3

const osoba = {
  imie: "Tomek",
  wiek: 25,
  opis() {
    return `${this.imie} ma ${this.wiek} lat`;
  },
};

console.log(osoba.opis()); // "Tomek ma 25 lat"

const konto = {
  saldo: 100,
  wplac(kwota) {
    this.saldo += kwota;
  },
  wyplac(kwota) {
    this.saldo -= kwota;
  },
};

konto.wplac(50);
konto.wyplac(30);
console.log(konto.saldo); // 120

function podajImie() {
  return this.imie;
}

const osobaA = { imie: "Ala", podajImie };
const osobaB = { imie: "Bartek", podajImie };

console.log(osobaA.podajImie()); // "Ala"
console.log(osobaB.podajImie()); // "Bartek"
// W wielu innych jezykach (np. self w Pythonie) kontekst "biezacego obiektu"
// jest ustalany przez SPOSOB DEFINICJI metody i pozostaje z nia zwiazany na
// stale. W JavaScript this jest DYNAMICZNE - ta sama funkcja podajImie
// zwraca rozne wyniki w zaleznosci od tego, PRZEZ KTORY obiekt zostala
// wywolana, mimo ze zostala zdefiniowana raz, w jednym miejscu.
